<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??'add'; if($action==='add'){ $name=trim($_POST['name']??'');$cat=$_POST['category']??'Other';$cost=max(0,(float)($_POST['cost_price']??0));$price=max(0,(float)($_POST['selling_price']??0));$qty=max(0,(int)($_POST['stock_qty']??0));$low=max(0,(int)($_POST['low_stock_level']??5));if($name){$st=$pdo->prepare("INSERT INTO products(name,category,cost_price,selling_price,stock_qty,low_stock_level) VALUES(?,?,?,?,?,?)");$st->execute([$name,$cat,$cost,$price,$qty,$low]);flash('Inventory item added.');}}elseif($action==='restock'){ $id=(int)$_POST['id'];$qty=max(0,(int)$_POST['qty']);$pdo->prepare("UPDATE products SET stock_qty=stock_qty+? WHERE id=?")->execute([$qty,$id]);flash('Stock updated.');} redirect('inventory.php');}
$rows=$pdo->query("SELECT * FROM products WHERE active=1 ORDER BY category,name")->fetchAll();$low=count(array_filter($rows,fn($r)=>$r['stock_qty']<=$r['low_stock_level']));layout_start('Inventory','inventory');?>
<div class="page-actions"><div><p class="muted">Manage retail stock, selling prices, cost, and reorder levels.</p><p class="tiny muted">Low-stock alerts: <b class="<?= $low?'danger-text':'success-text'?>"><?=$low?></b></p></div><button class="btn primary" onclick="document.getElementById('productForm').classList.toggle('hidden')">＋ Add item</button></div><section class="panel form-panel hidden" id="productForm"><h3>Add inventory item</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Item name *<input name="name" required placeholder="Swimming goggles"></label><label>Category<select name="category"><option>Tubes</option><option>Caps</option><option>Goggles</option><option>Shorts</option><option>Other</option></select></label><label>Cost price (₹)<input type="number" name="cost_price" min="0" step=".01" required></label><label>Selling price (₹)<input type="number" name="selling_price" min="0" step=".01" required></label><label>Opening stock<input type="number" name="stock_qty" min="0" value="0" required></label><label>Low stock at<input type="number" name="low_stock_level" min="0" value="5" required></label><div class="form-actions"><button class="btn primary">Save item</button></div></form></section><div class="stats-grid compact-stats"><article class="stat-card"><span class="muted">Active products</span><strong><?=count($rows)?></strong></article><article class="stat-card"><span class="muted">Stock valuation (cost)</span><strong><?=money(array_sum(array_map(fn($r)=>$r['cost_price']*$r['stock_qty'],$rows)))?></strong></article><article class="stat-card"><span class="muted">Low stock items</span><strong class="<?=$low?'danger-text':''?>"><?=$low?></strong></article></div><section class="panel table-panel"><div class="panel-head"><div><h3>Stock register</h3><p class="muted">Tubes, caps, goggles, shorts and more</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Cost</th><th>Price</th><th>Stock</th><th>Stock status</th><th>Restock</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h($r['name'])?></b></td><td><span class="badge soft"><?=h($r['category'])?></span></td><td><?=money($r['cost_price'])?></td><td><?=money($r['selling_price'])?></td><td class="strong"><?=$r['stock_qty']?></td><td><span class="badge <?=$r['stock_qty']<=$r['low_stock_level']?'warning':'success'?>"><?=$r['stock_qty']<=$r['low_stock_level']?'Low stock':'In stock'?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="restock"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="number" name="qty" min="1" value="5" aria-label="Quantity to add"><button class="btn small secondary">＋</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty">Add your first product to start tracking stock.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>
